import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    def opp_defections(start):
        count = 0
        total = 0
        i = start
        while i < n:
            total += 1
            if opp[i] == 'D':
                count += 1
            i += 1
        return count, total

    def recent_opp_defect_rate(k):
        start = n - k if n > k else 0
        count, total = opp_defections(start)
        if total == 0:
            return 0.0
        return count / float(total)

    # Always retaliate immediately after an opponent defection.
    if opp[n - 1] == 'D':
        return 'D'

    # First few rounds: cooperate, but watch for early exploitation.
    if n < 3:
        return 'C'

    # If opponent defected in the first 3 rounds at all, enter cautious mode:
    # defect until they show sustained cooperation, then forgive once.
    if n < 12:
        early_defects = 0
        for j in range(min(n, 6)):
            if opp[j] == 'D':
                early_defects += 1
        if early_defects >= 1:
            return 'D' if n < 8 else 'C'
        return 'C'

    r5 = recent_opp_defect_rate(5)
    r10 = recent_opp_defect_rate(10)
    r20 = recent_opp_defect_rate(20)

    # If opponent is highly cooperative, cooperate to maximize CC payoff.
    if r10 <= 0.1:
        return 'C'

    # If opponent is mostly defective, defect for 1 instead of 0.
    if r20 >= 0.65:
        return 'D'

    # Middle-ground: use a tit-for-tat-like rule with occasional forgiveness
    # to avoid long mutual-defection traps.
    if opp[n - 1] == 'D':
        return 'D'
    if n >= 2 and opp[n - 2] == 'D' and opp[n - 1] == 'C':
        # Forgive once after a single defection.
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Exploit slightly if opponent is too passive, but only rarely.
    if r20 < 0.15 and n > 30:
        if rng.random() < 0.015:
            return 'D'

    return 'C'
